class Animal {
  constructor(nome) {
    this.nome = nome;
  }
}

// Se "voar" e "nadar" forem modelados como classes base separadas,
// um Pato que precise das duas capacidades fica sem solução por extends.
class AnimalQueVoa extends Animal {
  voar() {
    console.log(`${this.nome} está a voar.`);
  }
}

class AnimalQueNada extends Animal {
  nadar() {
    console.log(`${this.nome} está a nadar.`);
  }
}

// Impossível: uma classe não pode estender duas classes ao mesmo tempo.
// class Pato extends AnimalQueVoa, AnimalQueNada {} -> SyntaxError

class Motor {
  constructor(potencia) {
    this.potencia = potencia;
  }

  arrancar() {
    console.log(`Motor a arrancar com ${this.potencia}cv.`);
  }
}

class SistemaTravagem {
  travar() {
    console.log('A travar...');
  }
}

class Carro {
  constructor(motor, travoes) {
    this.motor = motor; // "tem um" motor
    this.travoes = travoes; // "tem um" sistema de travagem
  }

  arrancar() {
    this.motor.arrancar();
  }

  travar() {
    this.travoes.travar();
  }
}

const carroDesportivo = new Carro(new Motor(450), new SistemaTravagem());
carroDesportivo.arrancar();

const SerializavelMixin = {
  paraJSON() {
    return JSON.stringify(this);
  }
};

const ComparavelMixin = {
  igualA(outro) {
    return JSON.stringify(this) === JSON.stringify(outro);
  }
};

class Produto {
  constructor(nome, preco) {
    this.nome = nome;
    this.preco = preco;
  }
}

Object.assign(Produto.prototype, SerializavelMixin, ComparavelMixin);

const produto1 = new Produto('Teclado', 49.9);
console.log(produto1.paraJSON()); // '{"nome":"Teclado","preco":49.9}'

const ComEventos = (Base) => class extends Base {
  #ouvintes = new Map();

  on(evento, callback) {
    if (!this.#ouvintes.has(evento)) this.#ouvintes.set(evento, []);
    this.#ouvintes.get(evento).push(callback);
    return this;
  }

  emitir(evento, ...args) {
    (this.#ouvintes.get(evento) ?? []).forEach((cb) => cb(...args));
  }
};

const ComHistorico = (Base) => class extends Base {
  #historico = [];

  registar(acao) {
    this.#historico.push({ acao, data: new Date() });
  }

  get historico() {
    return [...this.#historico];
  }
};

class ContaBancariaBase {
  constructor(saldo = 0) {
    this.saldo = saldo;
  }

  depositar(valor) {
    this.saldo += valor;
  }
}

class ContaBancaria extends ComEventos(ComHistorico(ContaBancariaBase)) {
  depositar(valor) {
    super.depositar(valor);
    this.registar(`deposito de ${valor}`);
    this.emitir('deposito', valor);
  }
}

const conta = new ContaBancaria(100);
conta.on('deposito', (valor) => console.log(`Depositado: ${valor}`));
conta.depositar(50);
console.log(conta.historico);

function aplicarMixins(Classe, ...mixins) {
  mixins.forEach((mixin) => {
    Object.getOwnPropertyNames(mixin).forEach((nome) => {
      if (nome === 'constructor') return;
      if (nome in Classe.prototype) {
        console.warn(`Aviso: "${nome}" já existe e vai ser sobrescrito.`);
      }
      Object.defineProperty(
        Classe.prototype,
        nome,
        Object.getOwnPropertyDescriptor(mixin, nome)
      );
    });
  });
}

const ComVoo = { mover() { console.log(`${this.nome} está a voar.`); } };
const ComNado = { mover() { console.log(`${this.nome} está a nadar.`); } };

class Pato {
  constructor(nome) {
    this.nome = nome;
  }
}

aplicarMixins(Pato, ComVoo, ComNado);
// Aviso: "mover" já existe e vai ser sobrescrito.

new Pato('Donald').mover(); // Donald está a nadar. (ComNado venceu por ser aplicado depois)

