class Impressora {
  imprimir(documento) {
    console.log(`A imprimir: ${documento}`);
  }
}

class Scanner {
  digitalizar(documento) {
    console.log(`A digitalizar: ${documento}`);
  }
}

class MultifuncoesEscritorio {
  constructor(impressora, scanner) {
    this.impressora = impressora;
    this.scanner = scanner;
  }

  imprimirDocumento(documento) {
    this.impressora.imprimir(documento);
  }

  digitalizarDocumento(documento) {
    this.scanner.digitalizar(documento);
  }
}

const multifuncoes = new MultifuncoesEscritorio(new Impressora(), new Scanner());
multifuncoes.imprimirDocumento('relatorio.pdf');
multifuncoes.digitalizarDocumento('contrato.pdf');

function aplicarMixinsSemColisao(Classe, ...mixins) {
  const jaAdicionados = new Set();

  mixins.forEach((mixin) => {
    Object.keys(mixin).forEach((nome) => {
      if (jaAdicionados.has(nome)) {
        throw new Error(`Conflito ao aplicar mixins: "${nome}" já foi definido por um mixin anterior.`);
      }
      Classe.prototype[nome] = mixin[nome];
      jaAdicionados.add(nome);
    });
  });
}

const ComArea = {
  calcular() {
    return this.largura * this.altura;
  }
};

const ComVolume = {
  calcular() {
    return this.largura * this.altura * this.profundidade;
  }
};

class Caixa {
  constructor(largura, altura, profundidade) {
    this.largura = largura;
    this.altura = altura;
    this.profundidade = profundidade;
  }
}

aplicarMixinsSemColisao(Caixa, ComVolume);
const caixa = new Caixa(2, 3, 4);
console.log(caixa.calcular()); // 24

try {
  aplicarMixinsSemColisao(Caixa, ComArea, ComVolume);
} catch (erro) {
  console.error(erro.message);
  // Conflito ao aplicar mixins: "calcular" já foi definido por um mixin anterior.
}

const ComValidacao = (Base) => class extends Base {
  validar(campos) {
    const emFalta = campos.filter(
      (campo) => this[campo] === undefined || this[campo] === null || this[campo] === ''
    );
    if (emFalta.length > 0) {
      throw new Error(`Campos em falta: ${emFalta.join(', ')}`);
    }
    return true;
  }
};

const ComAuditoria = (Base) => class extends Base {
  #registos = [];

  registar(acao) {
    this.#registos.push({ acao, quando: new Date() });
  }

  get registos() {
    return [...this.#registos];
  }
};

class Formulario {
  constructor(dados = {}) {
    Object.assign(this, dados);
  }
}

class FormularioContacto extends ComAuditoria(ComValidacao(Formulario)) {
  submeter(camposObrigatorios) {
    this.validar(camposObrigatorios);
    this.registar('submissao');
    return true;
  }
}

const formulario = new FormularioContacto({ nome: 'Ana', email: 'ana@exemplo.pt' });
console.log(formulario.submeter(['nome', 'email'])); // true
console.log(formulario.registos);

const formularioInvalido = new FormularioContacto({ nome: 'Bruno' });
try {
  formularioInvalido.submeter(['nome', 'email']);
} catch (erro) {
  console.error(erro.message); // Campos em falta: email
}
